}

function addEdit(value) {
  return (parent, key) => {
    if (Array.isArray(parent)) {
      const at = key === '-' ? parent.length : key;
      if (!isIndex(at) || at > parent.length) throw new OpFailure(`índice inválido para add: ${key}`);
